def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    opp_pressure = 0
    rich_opp_count = 0
    desperate_opp_count = 0

    for opp in alive_opponents:
        if opp.get('budget', 0) >= 500:
            rich_opp_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opp_count += 1

        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0)
            prev_bids.append(bid)
            if bid >= DAILY_SALARY * 1.2:
                opp_pressure += 2
            elif bid >= DAILY_SALARY * 0.85:
                opp_pressure += 1

    highest_prev_bid = max(prev_bids) if prev_bids else 0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    emergency = False
    if hp <= 2 or no_water_days >= 2:
        emergency = True

    danger = 0.0
    danger += scarcity * 0.9
    if hp <= 4:
        danger += 0.7
    if no_water_days >= 1:
        danger += 0.8
    danger += min(opp_pressure * 0.18, 0.6)
    danger += min(desperate_opp_count * 0.12, 0.36)

    if emergency:
        target = max(DAILY_SALARY * 0.95, highest_prev_bid + 2.0)
        if rich_opp_count >= 2:
            target = max(target, DAILY_SALARY * 1.1)
        return float(min(budget, target))

    if hp >= 8 and no_water_days == 0 and supply >= 21:
        if highest_prev_bid >= DAILY_SALARY * 1.2:
            return float(min(budget, DAILY_SALARY * 0.18))
        return float(min(budget, DAILY_SALARY * 0.28))

    if danger < 0.8:
        if highest_prev_bid >= DAILY_SALARY * 1.3:
            bid = DAILY_SALARY * 0.22
        elif highest_prev_bid > 0:
            bid = min(DAILY_SALARY * 0.48, avg_prev_bid * 0.72)
        else:
            bid = DAILY_SALARY * 0.4
    elif danger < 1.5:
        if highest_prev_bid >= DAILY_SALARY * 1.4 and hp >= 6 and no_water_days == 0:
            bid = DAILY_SALARY * 0.35
        else:
            bid = max(DAILY_SALARY * 0.58, highest_prev_bid + 1.5)
    else:
        bid = max(DAILY_SALARY * 0.82, highest_prev_bid + 3.0)
        if rich_opp_count >= 2:
            bid = max(bid, DAILY_SALARY * 0.95)

    if day >= 8 and hp <= 5:
        bid = max(bid, DAILY_SALARY * 0.9)

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget)
    elif budget > 800 and danger >= 1.0:
        bid = min(max(bid, DAILY_SALARY * 0.88), budget)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

