def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive = [o for o in opponents_status.values() if o.get('alive')]
    if not alive:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.35))

    # Extract yesterday bids from immediate previous_trace only
    prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Pressure proxy: if someone was bidding aggressively yesterday, others likely will too.
    # Also react to recent deaths (low bids) by bidding conservatively rather than mirroring.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: when supply is scarce, winning requires higher bids.
    # Normalize within [MIN_SUPPLY, MAX_SUPPLY].
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        scarcity = 0.5
    scarcity = max(0.0, min(1.0, float(scarcity)))

    # Base target bid: keep below aggressive bids unless we are at risk.
    # If others previously bid very high, we raise slightly; otherwise keep moderate.
    aggressive_threshold = DAILY_SALARY * 0.75
    if highest_prev_bid >= aggressive_threshold:
        base = DAILY_SALARY * (0.45 + 0.25 * scarcity)
    else:
        base = DAILY_SALARY * (0.35 + 0.20 * scarcity)

    # Risk adjustment: if our HP is low or we have many no-water days, bid more.
    # If we are healthy, bid less to preserve budget.
    if my_hp <= 2:
        base *= 1.8
    elif my_hp <= 4:
        base *= 1.35
    else:
        base *= 0.95

    if my_no_water_days >= 2:
        base *= 1.25

    # Cap by budget and also avoid overcommitting early.
    # If budget is already low, bid near what we can afford to avoid immediate bankruptcy.
    if my_budget <= DAILY_SALARY * 0.4:
        cap = my_budget
    else:
        cap = min(my_budget, DAILY_SALARY * 0.9)

    # Ensure non-negative bid.
    bid = max(0.0, min(cap, base))

    # If supply is extremely low, add a small bump to beat conservative strategies.
    if supply <= float(WATER_REQ):
        bid = min(cap, bid * 1.15)

    # Final rounding to reduce weird floats.
    return float(round(bid, 2))
